{
  "formName": "{{formName}}",
  "description": "Customer onboarding form",
  "rspId": {{rspId}},
  "fields": [
    {
      "referenceModel": "firstName",
      "visible": true,
      "shortLabel": "First Name",
      "longLabel": "Customer First Name",
      "validations": {
        "required": {
          "value": true,
          "message": "First name is required"
        },
        "minLength": {
          "value": 2,
          "message": "Minimum 2 characters required"
        }
      }
    },
    {
      "referenceModel": "lastName",
      "visible": true,
      "shortLabel": "Last Name",
      "longLabel": "Customer Last Name",
      "validations": {
        "required": {
          "value": true,
          "message": "Last name is required"
        }
      }
    },
    {
      "referenceModel": "address/city",
      "visible": true,
      "shortLabel": "City",
      "longLabel": "City of Residence",
      "validations": {
        "required": {
          "value": true,
          "message": "City is required"
        }
      }
    }
  ]
}

{
  "formName": "beneficiary-registration",
  "description": "Beneficiary setup form",
  "rspId": {{rspId}},
  "fields": [
    {
      "referenceModel": "fullName",
      "visible": true,
      "shortLabel": "Full Name",
      "longLabel": "Beneficiary Full Name",
      "validations": {
        "required": {
          "value": true,
          "message": "Beneficiary name is required"
        }
      }
    },
    {
      "referenceModel": "bankDetails/accountNumber",
      "visible": true,
      "shortLabel": "Account No",
      "longLabel": "Bank Account Number",
      "validations": {
        "required": {
          "value": true,
          "message": "Account number is required"
        },
        "pattern": {
          "pattern": "^[0-9]{8,20}$",
          "message": "Account number format is invalid"
        }
      }
    }
  ]
}

{
  "formName": "transaction-form",
  "description": "Transaction setup form",
  "rspId": {{rspId}},
  "fields": [
    {
      "referenceModel": "amount",
      "visible": true,
      "shortLabel": "Amount",
      "longLabel": "Transaction Amount",
      "validations": {
        "required": {
          "value": true,
          "message": "Amount is required"
        },
        "min": {
          "value": 1,
          "message": "Amount must be greater than zero"
        }
      }
    },
    {
      "referenceModel": "purpose",
      "visible": true,
      "shortLabel": "Purpose",
      "longLabel": "Transaction Purpose",
      "validations": {
        "required": {
          "value": true,
          "message": "Purpose is required"
        }
      }
    }
  ]
}

{
  "formName": "{{formName}}",
  "version": {{formVersion}},
  "fields": [
    {
      "referenceModel": "firstName",
      "shortLabelI18n": {
        "en": "First Name",
        "ne": "पहिलो नाम"
      },
      "longLabelI18n": {
        "en": "Customer First Name",
        "ne": "ग्राहकको पहिलो नाम"
      },
      "validations": [
        {
          "type": "required",
          "messageI18n": {
            "en": "First name is required",
            "ne": "पहिलो नाम आवश्यक छ"
          }
        },
        {
          "type": "minLength",
          "messageI18n": {
            "en": "Minimum 2 characters required",
            "ne": "कम्तिमा २ अक्षर आवश्यक छ"
          }
        }
      ]
    },
    {
      "referenceModel": "address/city",
      "shortLabelI18n": {
        "en": "City",
        "ne": "शहर"
      },
      "longLabelI18n": {
        "en": "City of Residence",
        "ne": "बसोबासको शहर"
      },
      "validations": [
        {
          "type": "required",
          "messageI18n": {
            "en": "City is required",
            "ne": "शहर आवश्यक छ"
          }
        }
      ]
    }
  ]
}

{
  "rspId": {{rspId}},
  "documentId": "{{documentId}}",
  "isPrimary": true,
  "fields": [
    {
      "referenceModel": "document/documentNumber",
      "visible": true,
      "shortLabel": "Document Number",
      "longLabel": "Supporting Document Number",
      "validations": {
        "required": {
          "value": true,
          "message": "Document number is required"
        },
        "minLength": {
          "value": 5,
          "message": "Document number must be at least 5 characters"
        },
        "maxLength": {
          "value": 20,
          "message": "Document number cannot exceed 20 characters"
        },
        "pattern": {
          "pattern": "^[A-Z0-9-]+$",
          "message": "Document number format is invalid"
        }
      }
    },
    {
      "referenceModel": "document/issueCountry/alphaTwoCode",
      "visible": true,
      "shortLabel": "Issue Country",
      "longLabel": "Document Issue Country",
      "validations": {
        "required": {
          "value": true,
          "message": "Issue country is required"
        }
      }
    },
    {
      "referenceModel": "document/issueDate",
      "visible": true,
      "shortLabel": "Issue Date",
      "longLabel": "Document Issue Date",
      "validations": {
        "allowPast": {
          "value": true,
          "message": "Issue date can be in the past"
        },
        "allowFuture": {
          "value": false,
          "message": "Issue date cannot be in the future"
        }
      }
    },
    {
      "referenceModel": "document/expiryDate",
      "visible": true,
      "shortLabel": "Expiry Date",
      "longLabel": "Document Expiry Date",
      "validations": {
        "required": {
          "value": false,
          "message": "Expiry date is required"
        },
        "allowPast": {
          "value": false,
          "message": "Expiry date cannot be in the past"
        },
        "allowFuture": {
          "value": true,
          "message": "Expiry date can be in the future"
        }
      }
    },
    {
      "referenceModel": "document/primaryContent",
      "visible": true,
      "shortLabel": "Front Side",
      "longLabel": "Primary Document Content",
      "validations": {
        "required": {
          "value": true,
          "message": "Primary content is required"
        }
      }
    },
    {
      "referenceModel": "document/secondaryContent",
      "visible": false,
      "shortLabel": "Back Side",
      "longLabel": "Secondary Document Content",
      "validations": {
        "required": {
          "value": false,
          "message": "Secondary content is required"
        }
      }
    }
  ]
}

{
  "rspId": {{rspId}},
  "documentId": "{{documentId}}",
  "isPrimary": true,
  "fields": [
    {
      "referenceModel": "document/documentNumber",
      "visible": true,
      "shortLabel": "Doc Number",
      "longLabel": "Updated Document Number",
      "validations": {
        "required": {
          "value": true,
          "message": "Document number is mandatory"
        },
        "minLength": {
          "value": 8,
          "message": "Document number must be at least 8 characters"
        },
        "pattern": {
          "pattern": "^[A-Z0-9]+$",
          "message": "Only uppercase letters and digits are allowed"
        }
      }
    },
    {
      "referenceModel": "document/expiryDate",
      "visible": true,
      "shortLabel": "Expiry Date",
      "longLabel": "Document Expiry Date",
      "validations": {
        "allowPast": {
          "value": false,
          "message": "Expiry date cannot be in the past"
        },
        "allowFuture": {
          "value": true,
          "message": "Expiry date can be in the future"
        }
      }
    },
    {
      "referenceModel": "document/secondaryContent",
      "visible": true,
      "shortLabel": "Back Side",
      "longLabel": "Back Document Upload",
      "validations": {
        "required": {
          "value": true,
          "message": "Back side upload is mandatory"
        }
      }
    }
  ]
}

{
  "setupId": "{{rspDocumentSetupId}}",
  "rspId": {{rspId}},
  "documentId": "{{documentId}}",
  "fields": [
    {
      "referenceModel": "document/documentNumber",
      "shortLabelI18n": {
        "en": "Document Number",
        "ne": "कागजात नम्बर"
      },
      "longLabelI18n": {
        "en": "Supporting Document Number",
        "ne": "समर्थन कागजात नम्बर"
      },
      "validations": {
        "required": {
          "messageI18n": {
            "en": "Document number is required",
            "ne": "कागजात नम्बर आवश्यक छ"
          }
        },
        "minLength": {
          "messageI18n": {
            "en": "Document number must be at least 5 characters",
            "ne": "कागजात नम्बर कम्तिमा ५ अक्षरको हुनुपर्छ"
          }
        },
        "pattern": {
          "messageI18n": {
            "en": "Document number format is invalid",
            "ne": "कागजात नम्बरको ढाँचा मिलेन"
          }
        }
      }
    },
    {
      "referenceModel": "document/expiryDate",
      "shortLabelI18n": {
        "en": "Expiry Date",
        "ne": "समाप्ति मिति"
