      "longLabelI18n": {
        "en": "Document Expiry Date",
        "ne": "कागजात समाप्ति मिति"
      },
      "validations": {
        "allowPast": {
          "messageI18n": {
            "en": "Expiry date cannot be in the past",
            "ne": "समाप्ति मिति विगतको हुन मिल्दैन"
          }
        },
        "allowFuture": {
          "messageI18n": {
            "en": "Expiry date can be in the future",
            "ne": "समाप्ति मिति भविष्यमा हुन सक्छ"
          }
        }
      }
    }
  ]
}
